"""The protected sleep window rule, per night of a game weekend.

start = the later of curfew and (last obligation end + wind-down buffer)
end   = the wake-up call; Saturday night ends at an assumed wake time instead,
        because Sunday is a player off day and nothing else bounds it.

Synthetic weekend (see tests/synthetic.py): Friday curfew 23:00 MT, wake-up
06:00 MT, meetings 21:00-22:00 MT, 30-minute wind-down buffer.
"""

from dataclasses import replace
from datetime import timedelta

import pytest

from sleep_scheduler.opportunity import evaluate
from sleep_scheduler.temporal import Interval, LocalTime
from sleep_scheduler.weekend import WindowOverride, build_weekend
from synthetic import ASSUMPTIONS, CHICAGO, DENVER, EARLY_KICKOFF, H, road_early_template

WITH_WAKE = replace(ASSUMPTIONS, saturday_night_wake="09:00")
NO_WAKE = replace(ASSUMPTIONS, saturday_night_wake=None)
M = timedelta(minutes=1)


def build(assumptions=WITH_WAKE, **kwargs):
    return build_weekend(
        road_early_template(),
        EARLY_KICKOFF,
        home_zone=CHICAGO,
        game_zone=DENVER,
        assumptions=assumptions,
        id="baseline",
        title="Early road kickoff (synthetic)",
        **kwargs,
    )


def night(weekend, name):
    return next(n for n in weekend.nights if n.night == name)


def test_friday_window_runs_from_curfew_to_wake_up_when_curfew_binds():
    window = night(build(), "fri").window
    assert window.interval.wall("start") == "2026-10-02T23:00"
    assert window.interval.wall("end") == "2026-10-03T06:00"
    assert (window.start_source, window.end_source) == ("curfew", "wake-up call")


def test_away_night_is_a_hotel_window_and_home_nights_are_home_windows():
    weekend = build()
    assert [night(weekend, n).window.kind for n in ("thu", "fri", "sat")] == ["home", "hotel", "home"]


def test_moving_friday_meetings_earlier_leaves_the_window_unchanged_while_curfew_binds():
    base = night(build(), "fri").window.interval
    moved = night(build(offsets={"fri-meeting": (-16 * H, -15 * H)}), "fri").window.interval
    assert moved == base


def test_meetings_ending_after_curfew_minus_buffer_shorten_the_night_by_the_overrun():
    # Meetings now end 22:50 MT; plus 30 minutes is 23:20, 20 minutes past curfew.
    base = night(build(), "fri").window
    late = night(build(offsets={"fri-meeting": (-13 * H, -12 * H - 10 * M)}), "fri").window
    assert late.interval.wall("start") == "2026-10-02T23:20"
    assert late.start_source == "obligation:fri-meeting"
    assert base.interval.duration - late.interval.duration == 20 * M


def test_the_wind_down_buffer_comes_from_the_assumption_set():
    late = night(
        build(
            assumptions=replace(WITH_WAKE, pre_bed_minutes=60),
            offsets={"fri-meeting": (-13 * H, -12 * H - 10 * M)},
        ),
        "fri",
    ).window
    assert late.interval.wall("start") == "2026-10-02T23:50"


def test_saturday_night_ends_at_the_assumed_wake_time_labelled_as_an_assumption():
    window = night(build(), "sat").window
    assert window.interval.wall("start") == "2026-10-03T23:00"
    assert window.interval.end_zone == CHICAGO
    assert window.interval.wall("end") == "2026-10-04T09:00"
    assert window.end_source == "assumed wake"


def test_late_return_shortens_saturday_night_against_the_assumed_wake():
    # Return charter 01:00 MT -> 04:00 CT Sunday; plus 30 minutes is 04:30.
    window = night(build(offsets={"sat-depart": (14 * H, 16 * H)}), "sat").window
    assert window.interval.wall("start") == "2026-10-04T04:30"
    assert window.start_source == "obligation:sat-depart"
    assert window.interval.duration == timedelta(hours=4, minutes=30)


def test_saturday_night_without_an_assumed_wake_time_is_refused():
    # Missing is not zero: an unbounded or silently empty Saturday would
    # misreport what a late return costs.
    with pytest.raises(ValueError, match="wake"):
        build(assumptions=NO_WAKE)


def test_staff_override_of_a_window_edge_is_applied_and_recorded():
    window = night(
        build(window_overrides={"fri": WindowOverride(start=LocalTime("2026-10-02T22:30", DENVER))}),
        "fri",
    ).window
    assert window.interval.wall("start") == "2026-10-02T22:30"
    assert (window.start_source, window.end_source) == ("staff override", "wake-up call")


def test_override_for_an_unknown_night_is_refused():
    with pytest.raises(ValueError, match="friday"):
        build(window_overrides={"friday": WindowOverride(start=LocalTime("2026-10-02T22:30", DENVER))})


def test_proposed_windows_are_on_the_scenario_so_evaluate_counts_them():
    weekend = build()
    report = evaluate(weekend.scenario, Interval.of("2026-10-02T18:00", "2026-10-03T12:00", DENVER))
    assert report.hours == 7.0
    assert all(w.proposed for w in weekend.scenario.windows)


def test_staff_override_of_the_end_is_what_obligations_are_judged_against():
    # Regression: the end override was applied after obligations were checked
    # against the rule's 06:00 wake-up, so a 04:30 treatment after a staff-set
    # 04:00 end still pushed the start and erased the window.
    from sleep_scheduler.schedule import Event

    treatment = Event(
        id="treatment",
        kind="treatment",
        title="Early treatment",
        interval=Interval.of("2026-10-03T04:30", "2026-10-03T05:00", DENVER),
    )
    plan = night(
        build(
            extra_events=[treatment],
            window_overrides={"fri": WindowOverride(end=LocalTime("2026-10-03T04:00", DENVER))},
        ),
        "fri",
    )
    assert plan.window is not None
    assert plan.window.interval.wall("start") == "2026-10-02T23:00"
    assert (plan.window.start_source, plan.window.end_source) == ("curfew", "staff override")


def test_obligation_inside_the_window_currently_pushes_the_start_rather_than_conflicting():
    # KNOWN LIMITATION, pinned so it cannot change silently. The rule cannot
    # tell "landed at 04:00" (sleep really starts after it) from "treatment at
    # 03:00" (should stay a visible conflict inside the window). Which
    # obligation kinds push the start is an open design question in STATUS.
    from sleep_scheduler.schedule import Event

    treatment = Event(
        id="treatment",
        kind="treatment",
        title="Overnight treatment",
        interval=Interval.of("2026-10-03T03:00", "2026-10-03T04:00", DENVER),
    )
    window = night(build(extra_events=[treatment]), "fri").window
    assert window.interval.wall("start") == "2026-10-03T04:30"
    assert window.start_source == "obligation:treatment"


def test_obligation_running_past_wake_up_leaves_no_window_and_says_why():
    # Meetings stretched to 06:30 MT Saturday, past the 06:00 wake-up call.
    plan = night(build(offsets={"fri-meeting": (-13 * H, -4 * H - 30 * M)}), "fri")
    assert plan.window is None
    assert "fri-meeting" in plan.note
"""Game-weekend files: what staff enter, rebuilt through build_weekend on load.

The file stores inputs (template, kickoff, zones, assumptions, overrides), not
resolved instants. Rebuilding on load is what keeps kickoff anchoring in one
place: change the kickoff in the file and every anchored event moves with it.
"""

import json

import pytest

from sleep_scheduler.persistence import (
    load_weekend,
    save_weekend,
    scenario_to_dict,
    weekend_from_dict,
    weekend_to_dict,
)
from sleep_scheduler.schedule import Event
from sleep_scheduler.temporal import Interval, LocalTime
from sleep_scheduler.weekend import WindowOverride, build_weekend
from synthetic import ASSUMPTIONS, CHICAGO, DENVER, EARLY_KICKOFF, H, road_early_template

MEETINGS_PAST_CURFEW = {"fri-meeting": (-13 * H, -12 * H - H / 6)}  # 22:00-22:50 MT


def build(**kwargs):
    return build_weekend(
        road_early_template(),
        EARLY_KICKOFF,
        home_zone=CHICAGO,
        game_zone=DENVER,
        assumptions=ASSUMPTIONS,
        id="baseline",
        title="Early road kickoff (synthetic)",
        **kwargs,
    )


def round_trip(weekend):
    return weekend_from_dict(json.loads(json.dumps(weekend_to_dict(weekend))))


def test_round_trip_rebuilds_the_same_events_and_windows():
    weekend = build()
    assert scenario_to_dict(round_trip(weekend).scenario) == scenario_to_dict(weekend.scenario)


def test_round_trip_keeps_the_template_kickoff_and_zones():
    weekend = build()
    restored = round_trip(weekend)
    assert restored.template == weekend.template
    assert restored.kickoff == weekend.kickoff
    assert (restored.home_zone, restored.game_zone) == (CHICAGO, DENVER)


def test_offset_overrides_are_stored_in_minutes_and_survive_the_round_trip():
    weekend = build(offsets=MEETINGS_PAST_CURFEW)
    payload = weekend_to_dict(weekend)
    assert payload["offsets"] == {"fri-meeting": {"start_minutes": -780, "end_minutes": -730}}
    assert scenario_to_dict(round_trip(weekend).scenario) == scenario_to_dict(weekend.scenario)


def test_window_overrides_and_extra_events_survive_the_round_trip():
    film = Event(
        id="thu-film",
        kind="meeting",
        title="Thursday film",
        interval=Interval.of("2026-10-01T19:00", "2026-10-01T20:00", CHICAGO),
    )
    weekend = build(
        extra_events=[film],
        window_overrides={"fri": WindowOverride(start=LocalTime("2026-10-02T22:30", DENVER))},
    )
    restored = round_trip(weekend)
    assert scenario_to_dict(restored.scenario) == scenario_to_dict(weekend.scenario)
    assert restored.scenario.windows[1].start_source == "staff override"


def test_editing_kickoff_in_the_file_moves_every_anchored_event():
    payload = weekend_to_dict(build())
    payload["kickoff"]["wall"] = "2026-10-03T11:30"
    moved = weekend_from_dict(payload)
    original = {e.id: e for e in build().scenario.events}
    for event in moved.scenario.events:
        assert event.interval.start - original[event.id].interval.start == H / 2


def test_a_plain_scenario_file_is_not_accepted_as_a_weekend():
    with pytest.raises(ValueError, match="game-weekend"):
        weekend_from_dict(scenario_to_dict(build().scenario))


def test_save_and_load_a_weekend_file(tmp_path):
    weekend = build(offsets=MEETINGS_PAST_CURFEW)
    path = tmp_path / "candidate.json"
    save_weekend(weekend, path)
    assert scenario_to_dict(load_weekend(path).scenario) == scenario_to_dict(weekend.scenario)
"""Instants, half-open intervals, and the interval algebra the spec requires.

The spec's temporal rules are the reason this module exists rather than bare
``datetime`` use: a local wall time plus an IANA zone is not always a single
instant, and the two cases where it is not must be refused rather than guessed.
Elapsed duration is always computed in UTC; zones are retained for rendering.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from typing import Iterable, Sequence
from zoneinfo import ZoneInfo

__all__ = [
    "AmbiguousLocalTime",
    "Interval",
    "InvalidInterval",
    "LocalTime",
    "NonexistentLocalTime",
    "TemporalError",
    "merge",
    "subtract",
    "total_duration",
]


class TemporalError(ValueError):
    """Base class for a local time or interval that cannot be trusted."""


class NonexistentLocalTime(TemporalError):
    """The wall time never occurs in that zone (spring-forward gap)."""


class AmbiguousLocalTime(TemporalError):
    """The wall time occurs twice in that zone and no fold was supplied."""


class InvalidInterval(TemporalError):
    """An interval whose end does not strictly follow its start."""


@dataclass(frozen=True)
class LocalTime:
    """A wall time entered by staff, kept alongside the zone it was entered in.

    ``fold`` is only meaningful for a repeated wall time: 0 selects the first
    occurrence (before the clocks go back), 1 the second. Supplying it for an
    unambiguous time is harmless and ignored.
    """

    wall: str
    zone: str
    fold: int | None = None

    def __post_init__(self) -> None:
        naive = datetime.fromisoformat(self.wall)
        if naive.tzinfo is not None:
            raise TemporalError(
                f"{self.wall!r} already carries an offset; pass a bare wall time "
                "and an IANA zone so the entered local context is preserved"
            )
        tz = ZoneInfo(self.zone)

        # A gap is detected by round-tripping: for a time that never occurred,
        # zoneinfo silently shifts it, so the return trip lands somewhere else.
        probe = naive.replace(tzinfo=tz)
        if probe.astimezone(timezone.utc).astimezone(tz).replace(tzinfo=None) != naive:
            raise NonexistentLocalTime(
                f"{self.wall} does not occur in {self.zone}; clocks skip that hour"
            )

        # A repeated time has two distinct offsets. zoneinfo would default to
        # fold=0 and quietly pick one, which the spec forbids.
        if probe.utcoffset() != naive.replace(tzinfo=tz, fold=1).utcoffset():
            if self.fold is None:
                raise AmbiguousLocalTime(
                    f"{self.wall} occurs twice in {self.zone}; supply fold=0 or fold=1"
                )

        object.__setattr__(self, "_naive", naive)
        object.__setattr__(self, "_tz", tz)

    @property
    def instant(self) -> datetime:
        """The single UTC instant this wall time and zone denote."""
        naive: datetime = getattr(self, "_naive")
        tz: ZoneInfo = getattr(self, "_tz")
        return naive.replace(tzinfo=tz, fold=self.fold or 0).astimezone(timezone.utc)

    def render(self, zone: str) -> str:
        """The same instant as wall time in another zone, for display only."""
        return self.instant.astimezone(ZoneInfo(zone)).isoformat()


@dataclass(frozen=True, order=True)
class Interval:
    """A half-open ``[start, end)`` span of UTC instants.

    Half-open is what lets a 22:00 event and a 22:00 window sit adjacent
    without being reported as a conflict.
    """

    start: datetime
    end: datetime
    # Provenance for rendering and export. Excluded from comparison so an
    # interval derived by merge/subtract still equals an equivalent entered one.
    start_zone: str | None = field(default=None, compare=False)
    end_zone: str | None = field(default=None, compare=False)
    start_fold: int | None = field(default=None, compare=False)
    end_fold: int | None = field(default=None, compare=False)

    def __post_init__(self) -> None:
        for name, value in (("start", self.start), ("end", self.end)):
            if value.tzinfo is None:
                raise InvalidInterval(f"{name} must be an aware instant, got {value!r}")
        object.__setattr__(self, "start", self.start.astimezone(timezone.utc))
        object.__setattr__(self, "end", self.end.astimezone(timezone.utc))

