    curfew: Edge | None
    wake: Edge | None
    at: str = "home"
    released_by: str | None = None

    def __post_init__(self) -> None:
        if (self.curfew is None) == (self.released_by is None):
            raise ValueError(
                f"night {self.night!r} needs exactly one of a curfew or released_by "
                "(the obligation whose end releases players)"
            )

