"""The staff CSV format: one week's itinerary in, one game weekend out.

Staff type the itinerary the way operations publishes it: a settings block,
then one row per item with a day and clock times. The confirmed decisions set
the anchoring, so there is no column for it. A kickoff offset (``K-4:15``) is
kickoff-anchored; a clock time before game day stays on the clock (Friday); a
clock time on game day or later becomes an offset from this file's kickoff
(Saturday follows kickoff). Curfew and wake-up rows become night markers, never
events. The full format is in SLEEP-SCHEDULER-SPEC.md, "Staff CSV format".

Import refuses what the model would otherwise accept silently: an unknown kind
(the model counts it as an obligation), a zero-length obligation, a duplicate
id, a night bounded twice or not at all. Every bad row is reported at once.
"""

from __future__ import annotations

import csv
import io
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from pathlib import Path
from zoneinfo import ZoneInfo

from .schedule import OPTIONAL_KINDS, AssumptionSet
from .temporal import LocalTime, TemporalError
from .weekend import (
    ClockTime,
    Edge,
    GameWeekend,
    KickoffBandTemplate,
    NightMarker,
    TemplateEntry,
    band_for,
    build_weekend,
)

__all__ = [
    "ALLOWED_KINDS",
    "CsvFormatError",
    "load_weekend_csv",
    "save_weekend_csv",
    "weekend_from_csv",
    "weekend_to_csv",
]

OBLIGATION_KINDS = frozenset(
    {"practice", "meeting", "walkthrough", "meal", "travel", "game", "treatment", "lift", "class", "media", "other"}
)
MARKER_KINDS = frozenset({"curfew", "wake-up"})
ALLOWED_KINDS = OBLIGATION_KINDS | OPTIONAL_KINDS | MARKER_KINDS
# The confirmed levers (Q7): a blank ``movable`` means yes for these only.
LEVER_KINDS = frozenset({"practice", "meeting", "travel"})

COLUMNS = ("kind", "day", "start", "end", "title", "at", "arrive_at", "movable", "releases", "id")
REQUIRED_SETTINGS = (
    "id",
    "title",
    "kickoff",
    "home_zone",
    "game_zone",
    "game_type",
    "source",
    "sleep_target_hours",
    "pre_bed_minutes",
    "morning_minutes",
    "assumptions_source",
)
OPTIONAL_SETTINGS = ("kickoff_at", "saturday_night_wake", "release_to_bed_minutes")

WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_FULL_DAYS = {"monday": "mon", "tuesday": "tue", "wednesday": "wed", "thursday": "thu",
              "friday": "fri", "saturday": "sat", "sunday": "sun"}
_CLOCK = re.compile(r"(\d{1,2}):([0-5]\d)")
_OFFSET = re.compile(r"K(?:([+-])(\d{1,3}):([0-5]\d))?", re.IGNORECASE)
_YES = {"yes", "y", "true"}
_NO = {"no", "n", "false"}


class CsvFormatError(ValueError):
    """The CSV cannot be read as an itinerary; the message names every bad row."""


def _fail(problems: list[str]) -> CsvFormatError:
    return CsvFormatError("itinerary CSV has problems:\n  " + "\n  ".join(problems))


# --- Import ------------------------------------------------------------------------


@dataclass(frozen=True)
class _Context:
    kickoff: datetime
    game_date: date
    zones: dict[str, str]


@dataclass
class _Night:
    curfew: tuple[Edge, str, int] | None = None
    wake: tuple[Edge, str, int] | None = None
    release: tuple[str, str, int] | None = None
    extra: list[str] | None = None


def _day_offset(text: str, game_date: date) -> int:
    name = _FULL_DAYS.get(text.lower(), text.lower())
    if name not in WEEKDAYS:
        raise ValueError(f"day {text!r} is not a weekday name such as Fri or Sat")
    offset = (WEEKDAYS.index(name) - game_date.weekday()) % 7
    return offset - 7 if offset > 3 else offset


def _clock(text: str) -> str | None:
    match = _CLOCK.fullmatch(text)
    if not match:
        return None
    hour, minute = int(match.group(1)), match.group(2)
    if hour > 23:
        raise ValueError(f"time {text!r} is not a 24-hour HH:MM")
    return f"{hour:02d}:{minute}"


def _offset(text: str) -> timedelta | None:
    match = _OFFSET.fullmatch(text)
    if not match:
        return None
    if match.group(1) is None:
        return timedelta()
    minutes = int(match.group(2)) * 60 + int(match.group(3))
    return timedelta(minutes=-minutes if match.group(1) == "-" else minutes)


def _place(text: str, what: str) -> tuple[str, str | timedelta]:
    if not text:
        raise ValueError(f"{what} is empty")
    offset = _offset(text)
    if offset is not None:
        return "offset", offset
    clock = _clock(text)
    if clock is not None:
        return "clock", clock
    raise ValueError(f"{what} {text!r} is neither HH:MM nor a kickoff offset like K-4:15")


def _edge(day: int, clock: str, zone: str, ctx: _Context) -> Edge:
    """A clock time before game day stays on the clock; later ones follow kickoff."""
    if day < 0:
        return ClockTime(day, clock)
    return LocalTime(f"{(ctx.game_date + timedelta(days=day)).isoformat()}T{clock}", zone).instant - ctx.kickoff


def _instant(edge: Edge, zone: str, ctx: _Context) -> datetime:
    if isinstance(edge, ClockTime):
        return edge.resolve(ctx.game_date, zone)
    return ctx.kickoff + edge


def _place_zone(text: str, what: str) -> str:
    value = (text or "home").lower()
    if value not in ("home", "away"):
        raise ValueError(f"{what} {text!r} must be home or away")
    return value


def _flag(text: str, what: str) -> bool | None:
    value = text.lower()
    if not value:
        return None
    if value in _YES:
        return True
    if value in _NO:
        return False
    raise ValueError(f"{what} {text!r} must be yes or no")


def _slug(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def _evening(instant: datetime, zone: str) -> date:
    local = instant.astimezone(ZoneInfo(zone))
    return local.date() if local.hour >= 12 else local.date() - timedelta(days=1)


def _read_settings(settings: dict[str, tuple[str, int]], problems: list[str]) -> tuple[dict, _Context] | None:
    for key in sorted(set(REQUIRED_SETTINGS) - set(settings)):
        problems.append(f"setting {key!r} is missing")
    for key, (_, line) in settings.items():
        if key not in REQUIRED_SETTINGS and key not in OPTIONAL_SETTINGS:
            problems.append(f"row {line}: unknown setting {key!r}")
    if problems:
        return None

    values = {key: value for key, (value, _) in settings.items()}
    line = lambda key: settings[key][1]  # noqa: E731
    try:
        for key in ("home_zone", "game_zone"):
            try:
                ZoneInfo(values[key])
            except Exception:
                raise ValueError(f"row {line(key)}: {key} {values[key]!r} is not an IANA zone")
        if values["game_type"] not in ("road", "home"):
            raise ValueError(f"row {line('game_type')}: game_type must be road or home (neutral site is road)")
        kickoff_at = _place_zone(values.get("kickoff_at", "away"), "kickoff_at")
        zones = {"home": values["home_zone"], "away": values["game_zone"]}
        kickoff = LocalTime(values["kickoff"].strip().replace(" ", "T", 1), zones[kickoff_at])
        assumptions = AssumptionSet(
            sleep_target_hours=float(values["sleep_target_hours"]),
            pre_bed_minutes=int(values["pre_bed_minutes"]),
            morning_minutes=int(values["morning_minutes"]),
            source=values["assumptions_source"],
            saturday_night_wake=_clock(values["saturday_night_wake"]) if values.get("saturday_night_wake") else None,
            release_to_bed_minutes=int(values["release_to_bed_minutes"])
            if values.get("release_to_bed_minutes")
            else None,
        )
    except (ValueError, TemporalError) as exc:
        problems.append(str(exc))
        return None

    instant = kickoff.instant
    ctx = _Context(instant, instant.astimezone(ZoneInfo(zones["away"])).date(), zones)
    return {"values": values, "kickoff": kickoff, "assumptions": assumptions}, ctx


def weekend_from_csv(text: str) -> GameWeekend:
    """Parse an itinerary CSV and build the game weekend it describes."""
    rows = [
        (number, [cell.strip() for cell in row])
        for number, row in enumerate(csv.reader(io.StringIO(text.lstrip("\ufeff"))), start=1)
    ]
    rows = [(number, cells) for number, cells in rows if any(cells)]
    if not rows or [c.lower() for c in rows[0][1][:2]] != ["setting", "value"]:
        raise _fail(["row 1: the file must start with a setting,value header"])

    problems: list[str] = []
    settings: dict[str, tuple[str, int]] = {}
    index = 1
    while index < len(rows) and rows[index][1][0].lower() != "kind":
        number, cells = rows[index]
        key = cells[0].lower()
        if key in settings:
            problems.append(f"row {number}: setting {key!r} given twice")
        settings[key] = (cells[1] if len(cells) > 1 else "", number)
        index += 1
    if index == len(rows):
        raise _fail(problems + ["the itinerary table header (kind,day,start,...) is missing"])
    header_line, header = rows[index]
    header = [cell.lower() for cell in header]
    while header and not header[-1]:
        header.pop()
    if tuple(header) != COLUMNS:
        problems.append(f"row {header_line}: table header must be {','.join(COLUMNS)}")

    parsed = _read_settings(settings, problems)
    if parsed is None or problems:
        raise _fail(problems)
    info, ctx = parsed

    entries: list[TemplateEntry] = []
    seen_ids: dict[str, int] = {}
    nights: dict[date, _Night] = {}

    for number, cells in rows[index + 1:]:
        row = dict(zip(COLUMNS, cells + [""] * (len(COLUMNS) - len(cells))))
        try:
            kind = row["kind"].lower()
            if kind not in ALLOWED_KINDS:
                raise ValueError(f"kind {row['kind']!r} is not one of {', '.join(sorted(ALLOWED_KINDS))}")
            at = _place_zone(row["at"], "at")
            start_form, start_value = _place(row["start"], "start")
            if start_form == "clock":
                if not row["day"]:
                    raise ValueError("a clock time needs a day")
                day = _day_offset(row["day"], ctx.game_date)

            if kind in MARKER_KINDS:
                if row["end"] or row["releases"] or row["arrive_at"]:
                    raise ValueError(f"a {kind} row has only a day, start, and at")
                zone = ctx.zones[at]
                edge = start_value if start_form == "offset" else _edge(day, start_value, zone, ctx)
                instant = _instant(edge, zone, ctx)
                if kind == "curfew":
                    night = nights.setdefault(_evening(instant, zone), _Night())
                    if night.curfew is not None:
                        raise ValueError("second curfew for the same night")
                    night.curfew = (edge, at, number)
                else:
                    local = instant.astimezone(ZoneInfo(zone)).date()
                    night = nights.setdefault(local - timedelta(days=1), _Night())
                    if night.wake is not None:
                        raise ValueError("second wake-up for the same night")
                    night.wake = (edge, at, number)
                continue

            arrive_at = _place_zone(row["arrive_at"], "arrive_at") if row["arrive_at"] else None
            start_zone, end_zone = ctx.zones[at], ctx.zones[arrive_at or at]
            end_form, end_value = _place(row["end"], "end")
            if start_form != end_form:
                raise ValueError("write start and end the same way: both HH:MM or both K offsets")
            if start_form == "offset":
                start, end = start_value, end_value
                if end <= start:
                    raise ValueError("end must follow start; enter a check-in as a 5-10 minute item")
                day_name = WEEKDAYS[(ctx.kickoff + start).astimezone(ZoneInfo(start_zone)).weekday()]
            else:
                if end_value == start_value:
                    raise ValueError("end equals start; enter a check-in as a 5-10 minute item")
                end_day = day + (1 if end_value < start_value else 0)
                if day < 0:
                    start, end = ClockTime(day, start_value), ClockTime(end_day, end_value)
                else:
                    start = _edge(day, start_value, start_zone, ctx)
                    end = _edge(end_day, end_value, end_zone, ctx)
                if _instant(end, end_zone, ctx) <= _instant(start, start_zone, ctx):
                    raise ValueError("end must follow start once zones are applied")
                day_name = WEEKDAYS[(ctx.game_date + timedelta(days=day)).weekday()]

            entry_id = row["id"] or f"{day_name}-{_slug(row['title'])}"
            if entry_id in seen_ids:
                raise ValueError(f"duplicate id {entry_id!r} (first used on row {seen_ids[entry_id]})")
            seen_ids[entry_id] = number
            movable = _flag(row["movable"], "movable")
            entries.append(
                TemplateEntry(
                    id=entry_id,
                    kind=kind,
                    title=row["title"],
                    start=start,
                    end=end,
                    start_at=at,
                    end_at=arrive_at,
                    movable=kind in LEVER_KINDS if movable is None else movable,
                )
            )
            if _flag(row["releases"], "releases"):
                night = nights.setdefault(_evening(_instant(end, end_zone, ctx), end_zone), _Night())
                if night.release is not None:
                    raise ValueError("second releases row for the same night")
                night.release = (entry_id, arrive_at or at, number)
        except (ValueError, TemporalError) as exc:
            problems.append(f"row {number}: {exc}")

    markers: list[NightMarker] = []
    for evening in sorted(nights):
        night, name = nights[evening], WEEKDAYS[evening.weekday()]
        start = night.curfew or night.release
        if night.curfew and night.release:
            problems.append(
                f"{name} night has both a curfew (row {night.curfew[2]}) and a releases row "
                f"(row {night.release[2]}); keep one"
            )
            continue
        if start is None:
            problems.append(f"{name} night has a wake-up (row {night.wake[2]}) but no curfew or releases row")
            continue
        if night.wake and night.wake[1] != start[1]:
            problems.append(f"{name} night: wake-up (row {night.wake[2]}) is not in the same place as its start")
            continue
        markers.append(
            NightMarker(
                night=name,
                curfew=night.curfew[0] if night.curfew else None,
                wake=night.wake[0] if night.wake else None,
                at=start[1],
                released_by=night.release[0] if night.release else None,
            )
        )

    if problems:
        raise _fail(problems)

    values = info["values"]
    template = KickoffBandTemplate(
        band=band_for(info["kickoff"], values["game_zone"]),
        game_type=values["game_type"],
        entries=tuple(entries),
        nights=tuple(markers),
        source=values["source"],
    )
    return build_weekend(
        template,
        info["kickoff"],
        home_zone=values["home_zone"],
        game_zone=values["game_zone"],
        assumptions=info["assumptions"],
        id=values["id"],
        title=values["title"],
    )


def load_weekend_csv(path: str | Path) -> GameWeekend:
    return weekend_from_csv(Path(path).read_text(encoding="utf-8-sig"))


# --- Export ------------------------------------------------------------------------


def _k(delta: timedelta) -> str:
    minutes = round(delta.total_seconds() / 60)
    sign = "-" if minutes < 0 else "+"
    return f"K{sign}{abs(minutes) // 60}:{abs(minutes) % 60:02d}"


def _written(edge: Edge, game_date: date, what: str) -> tuple[str, str]:
    """(day, time) cells for one edge, or a refusal if import would re-anchor it."""
    if isinstance(edge, ClockTime):
        if edge.day >= 0:
            raise CsvFormatError(
                f"{what} is a clock time on or after game day; the CSV format reads that as "
                "kickoff-anchored, so it cannot be written without changing its anchoring"
            )
        return WEEKDAYS[(game_date + timedelta(days=edge.day)).weekday()].capitalize(), edge.time
    return "", _k(edge)


def weekend_to_csv(weekend: GameWeekend) -> str:
    """Write a weekend in the staff format; refuses anything the format cannot hold."""
    if weekend.window_overrides:
        raise CsvFormatError("a weekend with a staff window override cannot be written as CSV")
    if weekend.extra_events:
        raise CsvFormatError("a weekend with an extra event placed outside the template cannot be written as CSV")
    if weekend.kickoff_entered is None:
        raise CsvFormatError("this weekend does not record the kickoff as entered")
    kickoff = weekend.kickoff_entered
    if kickoff.zone == weekend.game_zone:
        kickoff_at = "away"
    elif kickoff.zone == weekend.home_zone:
        kickoff_at = "home"
    else:
        raise CsvFormatError(f"kickoff zone {kickoff.zone} is neither the home nor the game zone")

    template, scenario = weekend.template, weekend.scenario
    assumptions = scenario.assumptions
    game_date = weekend.kickoff.astimezone(ZoneInfo(weekend.game_zone)).date()

    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["setting", "value"])
    settings = [
        ("id", scenario.id),
        ("title", scenario.title),
        ("kickoff", kickoff.wall.replace("T", " ")),
        ("kickoff_at", kickoff_at),
        ("home_zone", weekend.home_zone),
        ("game_zone", weekend.game_zone),
        ("game_type", template.game_type),
        ("source", template.source),
        ("sleep_target_hours", assumptions.sleep_target_hours),
        ("pre_bed_minutes", assumptions.pre_bed_minutes),
        ("morning_minutes", assumptions.morning_minutes),
        ("assumptions_source", assumptions.source),
        ("saturday_night_wake", assumptions.saturday_night_wake),
        ("release_to_bed_minutes", assumptions.release_to_bed_minutes),
    ]
    writer.writerows([key, value] for key, value in settings if value is not None)
    writer.writerow([])
    writer.writerow(COLUMNS)

    released = {marker.released_by for marker in template.nights if marker.released_by}
    for entry in template.entries:
        start, end = weekend.offsets.get(entry.id, (entry.start, entry.end))
        day, start_text = _written(start, game_date, f"entry {entry.id!r} start")
        end_day, end_text = _written(end, game_date, f"entry {entry.id!r} end")
        if isinstance(start, ClockTime):
            expected = start.day + (1 if end.time < start.time else 0)
            if end.day != expected:
                raise CsvFormatError(f"entry {entry.id!r} spans more than a day and cannot be written as CSV")
        writer.writerow([
            entry.kind, day, start_text, end_text, entry.title, entry.start_at, entry.end_at or "",
            "yes" if entry.movable else "no", "yes" if entry.id in released else "", entry.id,
        ])

    for marker in template.nights:
        for kind, edge, title in (("curfew", marker.curfew, "Curfew"), ("wake-up", marker.wake, "Wake-up call")):
            if edge is None:
                continue
            day, text = _written(edge, game_date, f"{marker.night} {kind}")
            writer.writerow([kind, day, text, "", title, marker.at, "", "", "", ""])
    return out.getvalue()


def save_weekend_csv(weekend: GameWeekend, path: str | Path) -> None:
    Path(path).write_text(weekend_to_csv(weekend), encoding="utf-8")

