"""The one-page printable comparison coaches and operations review (Package 3).

The terminal report (``cli.render_weekend_comparison``) is the content model;
this page says the same things for a reader who will not see a terminal. The
answer comes first, a row per night against the target, then what changed,
anything that needs sign-off, what set each sleep window, and every assumption
labelled as one.

Wording rules carry over. The page says "sleep opportunity", never sleep
obtained, and has no vocabulary for fatigue or effectiveness beyond saying none
is produced. Colour is never the only signal: every status is also words.

The file is self-contained (inline CSS, no scripts or external resources) so
it can be saved next to the itinerary on Drive, emailed, or printed to PDF.
"""

from __future__ import annotations

from datetime import date, datetime, timedelta
from html import escape
from zoneinfo import ZoneInfo

from .opportunity import Comparison
from .weekend import GameWeekend, NightReport, WeekendComparison

__all__ = ["render_comparison_html"]

NIGHT_NAMES = {
    "mon": "Monday", "tue": "Tuesday", "wed": "Wednesday", "thu": "Thursday",
    "fri": "Friday", "sat": "Saturday", "sun": "Sunday",
}


def _hm(hours: float) -> str:
    total = round(abs(hours) * 60)
    return f"{total // 60}h {total % 60:02d}m"


def _signed(hours: float) -> str:
    return ("+" if hours >= 0 else "-") + _hm(hours)


def _shift(delta: timedelta) -> str:
    minutes = round(delta.total_seconds() / 60)
    if minutes == 0:
        return "unchanged"
    size = abs(minutes)
    amount = f"{size} min" if size < 60 else f"{size // 60}h {size % 60:02d}m"
    return f"{amount} {'later' if minutes > 0 else 'earlier'}"


def _night_label(night: str) -> str:
    return f"{NIGHT_NAMES.get(night, night.capitalize())} night"


def _when(instant: datetime, zone: str) -> str:
    return instant.astimezone(ZoneInfo(zone)).strftime("%a %H:%M %Z")


def _titles(weekend: GameWeekend) -> dict[str, str]:
    return {event.id: event.title for event in weekend.scenario.events}


def _edge(source: str | None, weekend: GameWeekend) -> str:
    assumptions = weekend.scenario.assumptions
    titles = _titles(weekend)
    if source is None:
        return "not recorded"
    if source.startswith("obligation:"):
        event_id = source.split(":", 1)[1]
        return f"{titles.get(event_id, event_id)} ends + {assumptions.pre_bed_minutes} min wind-down"
    if source.startswith("release:"):
        event_id = source.split(":", 1)[1]
        return (
            f"{titles.get(event_id, event_id)} ends + "
            f"{assumptions.release_to_bed_minutes} min to bed (assumed)"
        )
    return {
        "curfew": "Curfew",
        "wake-up call": "Wake-up call",
        "assumed wake": "Assumed wake, Sunday off day",
        "staff override": "Staff override",
    }.get(source, source)


def _window_cell(night: NightReport, weekend: GameWeekend) -> str:
    window = night.plan.window
    if window is None:
        return f'<span class="none">No window</span><div class="why">{escape(night.note)}</div>'
    interval = window.interval
    span = f"{_when(interval.start, interval.start_zone)} &rarr; {_when(interval.end, interval.end_zone)}"
    why = (
        f"Start: {escape(_edge(window.start_source, weekend))}"
        f" &middot; End: {escape(_edge(window.end_source, weekend))}"
    )
    return f'{span}<div class="why">{why}</div>'


def _bar(hours: float, scale: float, kind: str) -> str:
    width = 0 if scale <= 0 else min(100.0, 100.0 * hours / scale)
    return f'<div class="bar {kind}" style="width:{width:.1f}%"></div>'


def _status(comparison: Comparison) -> str:
    short = comparison.candidate.shortfall_hours
    if short > 0:
        return f'<span class="status short">Short by {_hm(short)}</span>'
    return '<span class="status ok">Meets target</span>'


def render_comparison_html(comparison: WeekendComparison, *, generated: str | None = None) -> str:
    """The comparison as one printable, self-contained HTML page."""
    baseline, candidate = comparison.baseline.weekend, comparison.candidate.weekend
    assumptions = candidate.scenario.assumptions
    target = assumptions.sleep_target_hours
    generated = generated or date.today().isoformat()
    kickoff = candidate.kickoff.astimezone(ZoneInfo(candidate.game_zone))

    scale = max(
        [target]
        + [n.baseline.hours for _, n in comparison.nights]
        + [n.candidate.hours for _, n in comparison.nights]
    ) * 1.08
    target_left = 100.0 * target / scale

    result_rows = []
    for name, night in comparison.nights:
        result_rows.append(
            "<tr>"
            f'<th scope="row">{escape(_night_label(name))}</th>'
            f"<td>{_hm(night.baseline.hours)}</td>"
            f"<td>{_hm(night.candidate.hours)}</td>"
            f'<td class="diff">{_signed(night.hours_delta)}</td>'
            f'<td class="bars"><div class="track">'
            f"{_bar(night.baseline.hours, scale, 'base')}{_bar(night.candidate.hours, scale, 'cand')}"
            f'<div class="target" style="left:{target_left:.1f}%"></div></div></td>'
            f"<td>{_status(night)}</td>"
            "</tr>"
        )

    base_titles, cand_titles = _titles(baseline), _titles(candidate)
    changed = [
        f"<li><strong>{escape(cand_titles.get(c.event_id, c.event_id))}</strong>: "
        f"start {_shift(c.shift)}, end {_shift(c.end_shift)}</li>"
        for c in comparison.changed_events
    ]
    added = [f"<li><strong>{escape(cand_titles.get(i, i))}</strong>: added in the candidate</li>"
             for i in comparison.added_events]

    sign_off = []
    if comparison.kickoff_shift:
        sign_off.append(
            f"<li>Kickoff moved {_shift(comparison.kickoff_shift)}; kickoff is fixed, not a lever.</li>"
        )
    for change in comparison.fixed_event_changes:
        sign_off.append(
            f"<li><strong>{escape(cand_titles.get(change.event_id, change.event_id))}</strong> changed "
            f"(start {_shift(change.shift)}, end {_shift(change.end_shift)}); not a movable item.</li>"
        )
    for event_id in comparison.removed_events:
        sign_off.append(
            f"<li><strong>{escape(base_titles.get(event_id, event_id))}</strong> is missing from the "
            "candidate; dropping an obligation is not a lever.</li>"
        )

    window_rows = []
    for base_night, cand_night in zip(comparison.baseline.nights, comparison.candidate.nights):
        window_rows.append(
            "<tr>"
            f'<th scope="row">{escape(_night_label(base_night.night))}</th>'
            f"<td>{_window_cell(base_night, baseline)}</td>"
            f"<td>{_window_cell(cand_night, candidate)}</td>"
            "</tr>"
        )

    conflicts = [
        f"<li>{label} {escape(_night_label(night.night))}: "
        f"<strong>{escape(_titles(weekend).get(c.event_id, c.event_id))}</strong> overlaps the sleep window "
        f"by {_hm(c.overlap.duration.total_seconds() / 3600)}</li>"
        for label, report, weekend in (
            ("Baseline", comparison.baseline, baseline),
            ("Candidate", comparison.candidate, candidate),
        )
        for night in report.nights
        for c in night.report.conflicts
    ]

    assumption_items = [
        f"{_hm(target)} target ({escape(assumptions.source)})",
        f"{assumptions.pre_bed_minutes} min wind-down after the last obligation (assumption)",
    ]
    if assumptions.release_to_bed_minutes is not None:
        assumption_items.append(
            f"{assumptions.release_to_bed_minutes} min from release to bed on a night with no curfew (assumption)"
        )
    if assumptions.saturday_night_wake:
        assumption_items.append(
            f"Saturday night ends at {escape(assumptions.saturday_night_wake)} (assumption; Sunday is an off day)"
        )
    if assumptions.morning_minutes:
        assumption_items.append(
            f"{assumptions.morning_minutes} min before a morning obligation (assumption)"
        )

    def section(title: str, items: list[str], empty: str) -> str:
        body = f"<ul>{''.join(items)}</ul>" if items else f'<p class="quiet">{empty}</p>'
        return f"<section><h2>{title}</h2>{body}</section>"

    sign_off_html = (
        f'<section class="signoff"><h2>Needs sign-off</h2><ul>{"".join(sign_off)}</ul></section>'
        if sign_off
        else '<section><h2>Sign-off</h2><p class="quiet">Only movable items changed.</p></section>'
    )

    return f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sleep opportunity comparison</title>
<style>
:root {{
  --ink: #1d232a; --muted: #5b6570; --rule: #d9dee3; --panel: #f4f6f8;
  --base: #9aa5b1; --cand: #1f5f8b; --short: #9b2c1f; --ok: #2d6a3e; --target: #1d232a;
}}
@page {{ size: letter; margin: 0.45in; }}
* {{ box-sizing: border-box; }}
html {{ background: #fff; }}
body {{ margin: 0 auto; max-width: 7.6in; padding: 16px; color: var(--ink); background: #fff;
  font: 10pt/1.35 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }}
header {{ border-bottom: 2px solid var(--ink); padding-bottom: 6px; margin-bottom: 10px; }}
h1 {{ font-size: 16pt; margin: 0; letter-spacing: -0.01em; }}
.measure {{ margin: 2px 0 6px; color: var(--muted); }}
.meta {{ display: grid; grid-template-columns: auto 1fr; gap: 1px 10px; margin: 0; font-size: 9pt; }}
.meta dt {{ color: var(--muted); }} .meta dd {{ margin: 0; }}
h2 {{ font-size: 10.5pt; margin: 12px 0 4px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }}
table {{ width: 100%; border-collapse: collapse; }}
th, td {{ text-align: left; padding: 4px 6px; border-bottom: 1px solid var(--rule); vertical-align: top; }}
thead th {{ font-size: 8.5pt; color: var(--muted); font-weight: 600; }}
.results td, .results th {{ vertical-align: middle; }}
.diff {{ font-variant-numeric: tabular-nums; font-weight: 600; }}
td {{ font-variant-numeric: tabular-nums; }}
.bars {{ width: 34%; }}
.track {{ position: relative; height: 18px; }}
.bar {{ height: 7px; margin: 1px 0; border-radius: 2px; }}
.bar.base {{ background: var(--base); }} .bar.cand {{ background: var(--cand); }}
.target {{ position: absolute; top: -2px; bottom: -2px; border-left: 2px dashed var(--target); }}
.legend {{ font-size: 8.5pt; color: var(--muted); margin: 3px 0 0; }}
.swatch {{ display: inline-block; width: 10px; height: 7px; border-radius: 2px; margin: 0 3px 0 8px; }}
.status {{ font-weight: 600; white-space: nowrap; }}
.status.short {{ color: var(--short); }} .status.ok {{ color: var(--ok); }}
.why {{ color: var(--muted); font-size: 8.5pt; }}
.none {{ color: var(--short); font-weight: 600; }}
.cols {{ display: grid; grid-template-columns: 1fr 1fr; gap: 0 18px; }}
ul {{ margin: 0; padding-left: 16px; }} li {{ margin: 1px 0; }}
.quiet {{ margin: 0; color: var(--muted); }}
.signoff {{ background: #fbeeea; border-left: 3px solid var(--short); padding: 2px 8px 6px; }}
.signoff h2 {{ color: var(--short); }}
.assumptions {{ background: var(--panel); padding: 2px 8px 6px; }}
footer {{ margin-top: 10px; padding-top: 6px; border-top: 1px solid var(--rule); font-size: 8.5pt; color: var(--muted); }}
footer p {{ margin: 2px 0; }}
@media (max-width: 640px) {{ .cols {{ grid-template-columns: 1fr; }} .bars {{ display: none; }} }}
@media print {{ body {{ padding: 0; max-width: none; }} section, table {{ break-inside: avoid; }}
  .signoff, .assumptions {{ -webkit-print-color-adjust: exact; print-color-adjust: exact; }} }}
</style>
</head>
<body>
<header>
<h1>Sleep opportunity comparison</h1>
<p class="measure">Sleep opportunity, not sleep obtained, per night of the game weekend.</p>
<dl class="meta">
<dt>Baseline</dt><dd>{escape(baseline.scenario.title)}</dd>
<dt>Candidate</dt><dd>{escape(candidate.scenario.title)}</dd>
<dt>Kickoff</dt><dd>{kickoff:%a %b %d, %Y %H:%M %Z} ({escape(candidate.template.band)} band, {escape(candidate.template.game_type)} game)</dd>
<dt>Source</dt><dd>{escape(candidate.template.source)}</dd>
</dl>
</header>

<section>
<h2>Result by night</h2>
<table class="results">
<thead><tr><th>Night</th><th>Baseline</th><th>Candidate</th><th>Change</th><th>Target {_hm(target)}</th><th>Candidate vs target</th></tr></thead>
<tbody>
{chr(10).join(result_rows)}
</tbody>
</table>
<p class="legend"><span class="swatch" style="background:var(--base)"></span>Baseline<span class="swatch" style="background:var(--cand)"></span>Candidate<span class="swatch" style="border-left:2px dashed var(--target);border-radius:0;width:2px"></span>Target</p>
</section>

<div class="cols">
{section("What changed", changed + added, "Nothing changed between the two schedules.")}
{sign_off_html}
</div>

<section>
<h2>Sleep windows and what set each edge</h2>
<table>
<thead><tr><th>Night</th><th>Baseline</th><th>Candidate</th></tr></thead>
<tbody>
{chr(10).join(window_rows)}
</tbody>
</table>
</section>

<div class="cols">
{section("Conflicts (not resolved automatically)", conflicts, "No obligation overlaps a sleep window.")}
<section class="assumptions"><h2>Assumptions</h2><ul>{"".join(f"<li>{item}</li>" for item in assumption_items)}</ul></section>
</div>

<footer>
<p>Sleep opportunity is time available for sleep, not sleep obtained.</p>
<p>No fatigue or effectiveness forecast is produced: no forecasting engine has been evaluated for this population.</p>
<p>Generated {escape(generated)} by sleep-scheduler. Times are local to where each night is spent.</p>
</footer>
</body>
</html>
"""

