The terminal report (``cli.render_weekend_comparison``) is the content model;
this page says the same things for a reader who will not see a terminal. The
answer comes first, a row per night against the target, then what changed,
anything that needs sign-off, what set each sleep window, and every assumption
labelled as one.

Wording rules carry over. The page says "sleep opportunity", never sleep
obtained, and has no vocabulary for fatigue or effectiveness beyond saying none
is produced. Colour is never the only signal: every status is also words.

The file is self-contained (inline CSS, no scripts or external resources) so
it can be saved next to the itinerary on Drive, emailed, or printed to PDF.
"""

from __future__ import annotations

from datetime import date, datetime, timedelta
from html import escape
from zoneinfo import ZoneInfo

from .opportunity import Comparison
from .weekend import GameWeekend, NightReport, WeekendComparison

__all__ = ["render_comparison_html"]

NIGHT_NAMES = {
    "mon": "Monday", "tue": "Tuesday", "wed": "Wednesday", "thu": "Thursday",
    "fri": "Friday", "sat": "Saturday", "sun": "Sunday",
}


def _hm(hours: float) -> str:
    total = round(abs(hours) * 60)
    return f"{total // 60}h {total % 60:02d}m"


def _signed(hours: float) -> str:
    return ("+" if hours >= 0 else "-") + _hm(hours)


def _shift(delta: timedelta) -> str:
    minutes = round(delta.total_seconds() / 60)
    if minutes == 0:
        return "unchanged"
    size = abs(minutes)
    amount = f"{size} min" if size < 60 else f"{size // 60}h {size % 60:02d}m"
    return f"{amount} {'later' if minutes > 0 else 'earlier'}"


def _night_label(night: str) -> str:
    return f"{NIGHT_NAMES.get(night, night.capitalize())} night"


def _when(instant: datetime, zone: str) -> str:
    return instant.astimezone(ZoneInfo(zone)).strftime("%a %H:%M %Z")


def _titles(weekend: GameWeekend) -> dict[str, str]:
    return {event.id: event.title for event in weekend.scenario.events}


def _edge(source: str | None, weekend: GameWeekend) -> str:
    assumptions = weekend.scenario.assumptions
    titles = _titles(weekend)
    if source is None:
        return "not recorded"
    if source.startswith("obligation:"):
        event_id = source.split(":", 1)[1]
        return f"{titles.get(event_id, event_id)} ends + {assumptions.pre_bed_minutes} min wind-down"
    if source.startswith("release:"):
        event_id = source.split(":", 1)[1]
        return (
            f"{titles.get(event_id, event_id)} ends + "
            f"{assumptions.release_to_bed_minutes} min to bed (assumed)"
        )
    return {
        "curfew": "Curfew",
        "wake-up call": "Wake-up call",
        "assumed wake": "Assumed wake, Sunday off day",
        "staff override": "Staff override",
    }.get(source, source)


def _window_cell(night: NightReport, weekend: GameWeekend) -> str:
    window = night.plan.window
    if window is None:
        return f'<span class="none">No window</span><div class="why">{escape(night.note)}</div>'
    interval = window.interval
    span = f"{_when(interval.start, interval.start_zone)} &rarr; {_when(interval.end, interval.end_zone)}"
    why = (
        f"Start: {escape(_edge(window.start_source, weekend))}"
        f" &middot; End: {escape(_edge(window.end_source, weekend))}"
